mapper.select:
SELECT DATE(create_time) as reportDate, 'summary' as reportType, COALESCE(SUM(total_amount), 0) as totalSalesAmount, COUNT(*) as totalOrderCount, COALESCE(AVG(total_amount), 0) as avgOrderAmount FROM sales_out WHERE status = 'approved'
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(create_time) ORDER BY reportDate DESC

SELECT DATE(create_time) as reportDate, 'summary' as reportType, COALESCE(SUM(total_amount), 0) as totalPurchaseAmount, COUNT(*) as totalOrderCount, COALESCE(AVG(total_amount), 0) as avgOrderAmount FROM purchase_in WHERE status = 'approved'
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(create_time) ORDER BY reportDate DESC

SELECT i.id, i.product_id as productId, p.product_name as productName, p.product_code as productCode, w.warehouse_name as warehouseName, l.location_name as locationName, i.quantity, i.min_quantity as minQuantity, i.max_quantity as maxQuantity, i.unit_price as unitPrice, i.quantity * i.unit_price as totalAmount, i.last_in_time as lastInTime, i.last_out_time as lastOutTime FROM inventory i LEFT JOIN product p ON i.product_id = p.id LEFT JOIN warehouse w ON i.warehouse_id = w.id LEFT JOIN location l ON i.location_id = l.id
AND i.warehouse_id = #{warehouseId}
AND i.product_id = #{productId}

SELECT DATE(create_time) as date, COALESCE(SUM(total_amount), 0) as amount, COUNT(*) as count FROM sales_out WHERE status = 'approved'
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(create_time) ORDER BY date ASC

SELECT DATE(create_time) as date, COALESCE(SUM(total_amount), 0) as amount, COUNT(*) as count FROM purchase_in WHERE status = 'approved'
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(create_time) ORDER BY date ASC

SELECT c.id as customerId, c.customer_name as customerName, COALESCE(SUM(so.total_amount), 0) as totalSalesAmount, COUNT(so.id) as orderCount, COALESCE(SUM(so.total_amount), 0) as totalReceivable, COALESCE(SUM(so.total_amount), 0) as receivedAmount, 0 as pendingAmount, MAX(so.create_time) as lastOrderDate, CASE WHEN COALESCE(SUM(so.total_amount), 0) > 0 THEN ROUND(COALESCE(SUM(so.total_amount), 0) / COALESCE(SUM(so.total_amount), 0) * 100, 2) ELSE 0 END as paymentRate, c.customer_level as customerLevel FROM customer c LEFT JOIN sales_out so ON c.id = so.customer_id AND so.status = 'approved'
AND DATE(so.create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY c.id, c.customer_name, c.customer_level ORDER BY totalSalesAmount DESC

SELECT p.id as productId, p.product_name as productName, pc.category_name as categoryName, COALESCE(SUM(sod.quantity), 0) as salesQuantity, COALESCE(SUM(sod.quantity * sod.unit_price), 0) as salesAmount, COALESCE(SUM(pid.quantity), 0) as purchaseQuantity, COALESCE(SUM(pid.quantity * pid.unit_price), 0) as purchaseAmount, COALESCE(SUM(i.quantity), 0) as stockQuantity, COALESCE(SUM(i.quantity * i.unit_price), 0) as stockAmount, COALESCE(SUM(sod.quantity * sod.unit_price), 0) - COALESCE(SUM(pid.quantity * pid.unit_price), 0) as profit, CASE WHEN COALESCE(SUM(sod.quantity * sod.unit_price), 0) > 0 THEN ROUND((COALESCE(SUM(sod.quantity * sod.unit_price), 0) - COALESCE(SUM(pid.quantity * pid.unit_price), 0)) / COALESCE(SUM(sod.quantity * sod.unit_price), 0) * 100, 2) ELSE 0 END as profitRate, MAX(sod.create_time) as lastSalesDate FROM product p LEFT JOIN sales_out_detail sod ON p.id = sod.product_id LEFT JOIN purchase_in_detail pid ON p.id = pid.product_id LEFT JOIN product_category pc ON p.category_id = pc.id LEFT JOIN inventory i ON p.id = i.product_id
WHERE DATE(sod.create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY p.id, p.product_name, pc.category_name ORDER BY salesAmount DESC

SELECT s.id as supplierId, s.supplier_name as supplierName, COALESCE(SUM(pi.total_amount), 0) as totalPurchaseAmount, COUNT(pi.id) as orderCount, COALESCE(SUM(pi.total_amount), 0) as totalPayable, COALESCE(SUM(pi.total_amount), 0) as paidAmount, 0 as pendingAmount, MAX(pi.create_time) as lastOrderDate, CASE WHEN COALESCE(SUM(pi.total_amount), 0) > 0 THEN ROUND(COALESCE(SUM(pi.total_amount), 0) / COALESCE(SUM(pi.total_amount), 0) * 100, 2) ELSE 0 END as paymentRate, s.supplier_level as supplierLevel FROM supplier s LEFT JOIN purchase_in pi ON s.id = pi.supplier_id AND pi.status = 'approved'
AND DATE(pi.create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY s.id, s.supplier_name, s.supplier_level ORDER BY totalPurchaseAmount DESC
